def tier(words):
    """(low, high) embed range for a post of this length, from the standard."""
    if words < 1000:
        return 1, 2
    if words <= 2500:
        return 4, 5
    return 7, 8


def norm(s):
    s = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", s)
    return re.sub(r"\s+", " ", re.sub(r"[*_`#>]", "", s)).strip().lower()


def embed_key(url):
    """One key per embed, so x.com and twitter.com or two YouTube url shapes match."""
    u = url.strip().split("?")[0].rstrip("/")
    m = re.search(r"(?:youtu\.be/|v=|/shorts/|/embed/)([\w-]{11})", url)
    if m:
        return "yt:" + m.group(1)
    m = re.search(r"/status/(\d+)", u)
    if m:
        return "x:" + m.group(1)
    return u.lower()


def thumb(data):
    try:
        from PIL import Image
        return Image.open(io.BytesIO(data)).convert("L").resize((64, 36))
    except Exception:
        return None


def same_pixels(a, b):
    from PIL import ImageChops, ImageStat
    return ImageStat.Stat(ImageChops.difference(a, b)).mean[0] < 3


def split_frontmatter(text):
    lines = text.split("\n")
    if lines and lines[0].strip() == "---":
        for k in range(1, len(lines)):
            if lines[k].strip() == "---":
                return lines[:k + 1], lines[k + 1:], k + 1
